AND t.config_id = #{id}
AND t1.tenant_id = #{tenantId}
AND t1.industry_code = #{industryCode}
AND t.vehicle_number like CONCAT(CONCAT('%', #{key}),'%')
AND t.black_or_white = #{blackOrWhiteInt}
AND t.config_id in
#{id}
order by t1.create_time desc ,t.vehicle_number

