SELECT DISTINCT t.id, t.tenant_id, t.industry_code, t.device_code, t.device_name, t.channel_code, t.channel_name, t.alarm_type, t.alarm_type_name, t.second_switch, t.algorithm_code, t.algorithm_name, t.trigger_rule as triggerRuleStr FROM vm_algorithm_give_config t WHERE t.delete_flag = 0 and (t.tenant_id != #{tenantId} or t.industry_code != #{industryCode})
and t.device_code = #{deviceCode}
and t.channel_code = #{channelCode}
and t.alarm_type = #{alarmType}
order by t.create_time desc limit 1

SELECT DISTINCT device_code, algorithm_code
FROM vm_order_algorithm_config
WHERE delete_flag = 0
  AND algorithm_type = 1
  AND order_code = #{orderCode}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}

mapper.update:
UPDATE vm_algorithm_give_config
SET second_switch = '1',
    algorithm_code = NULL,
    algorithm_name = NULL,
    update_time = now(),
    modifier = 'order'
WHERE order_code = #{orderCode}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND NOT EXISTS (
      SELECT 1 FROM vm_order_algorithm_config oac
      WHERE oac.order_code = #{orderCode}
        AND oac.tenant_id = #{tenantId}
        AND oac.industry_code = #{industryCode}
        AND oac.delete_flag = 0
        AND oac.algorithm_type = 1
        AND oac.device_code = vm_algorithm_give_config.device_code
        AND oac.algorithm_code = vm_algorithm_give_config.algorithm_code
  )

UPDATE vm_video_preset
SET is_algorithm_identify = '0',
    algorithm_code = NULL,
    update_time = now()
WHERE order_code = #{orderCode}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND delete_flag = 0
  AND is_algorithm_identify = '1'
  AND NOT EXISTS (
      SELECT 1 FROM vm_order_algorithm_config oac
      WHERE oac.order_code = #{orderCode}
        AND oac.tenant_id = #{tenantId}
        AND oac.industry_code = #{industryCode}
        AND oac.delete_flag = 0
        AND oac.algorithm_type = 1
        AND oac.device_code = vm_video_preset.device_code
        AND oac.algorithm_code = vm_video_preset.algorithm_code
  )

mapper.select:
SELECT DISTINCT device_code, channel_code
FROM vm_algorithm_give_config
WHERE order_code = #{orderCode}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND NOT EXISTS (
      SELECT 1 FROM vm_order_algorithm_config oac
      WHERE oac.order_code = #{orderCode}
        AND oac.tenant_id = #{tenantId}
        AND oac.industry_code = #{industryCode}
        AND oac.delete_flag = 0
        AND oac.algorithm_type = 1
        AND oac.device_code = vm_algorithm_give_config.device_code
        AND oac.algorithm_code = vm_algorithm_give_config.algorithm_code
  )

SELECT DISTINCT device_code, channel_code
FROM vm_algorithm_give_config
WHERE order_code = #{orderCode}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND NOT EXISTS (
      SELECT 1
      FROM vm_order_devices e
      INNER JOIN vm_order_algorithms a
          ON e.order_code = a.order_code
         AND e.tenant_id = a.tenant_id
         AND a.package_code = e.package_code
         AND a.industry_code = e.industry_code
      WHERE a.delete_flag = '0'
        AND e.delete_flag = '0'
        AND a.ord_status in (0, 1, 2)
        AND e.ord_status in (0, 1, 2)
        AND a.order_code = #{orderCode}
        AND a.tenant_id = #{tenantId}
        AND a.industry_code = #{industryCode}
        AND e.device_code = vm_algorithm_give_config.device_code
        AND a.algorithm_code = vm_algorithm_give_config.algorithm_code
  )
